package com.mamtrex.hospital.audit;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_events") public class AuditEvent extends BaseEntity { @Column(nullable=false) private String actor; @Column(nullable=false) private String action; private String resourceType; private String resourceId; @Column(length=2000) private String details; private Instant occurredAt=Instant.now(); protected AuditEvent(){} public AuditEvent(String actor,String action,String resourceType,String resourceId,String details){this.actor=actor;this.action=action;this.resourceType=resourceType;this.resourceId=resourceId;this.details=details;} public String getActor(){return actor;} public String getAction(){return action;} public String getResourceType(){return resourceType;} public String getResourceId(){return resourceId;} public String getDetails(){return details;} public Instant getOccurredAt(){return occurredAt;} }
